"""`.Position General`: generated by export_nodes.py from library.blend; kept by hand from then on."""

NAME = '.Position General'
KIND = 'ShaderNodeTree'


def build(lib):
    t = lib.new_group(NAME, KIND, props={})

    t.socket('OUTPUT', 'Pattern position (base)', 'NodeSocketVector', min_value=0.0, max_value=0.0)
    t.socket('OUTPUT', 'Pattern position (red)', 'NodeSocketVector', min_value=0.0, max_value=0.0)
    t.socket('OUTPUT', 'Pattern position (green)', 'NodeSocketVector', min_value=0.0, max_value=0.0)
    t.socket('OUTPUT', 'Pattern position (blue)', 'NodeSocketVector', min_value=0.0, max_value=0.0)

    t.node('NodeFrame', 'Frame', props={
        'location': (-202.42105, 290.42102),
        'width': 198.73685,
        'height': 279.99997,
        'label': 'Base Pattern position',
    })
    t.node('NodeFrame', 'Frame.001', props={
        'location': (-202.42105, -2.0),
        'width': 198.73685,
        'height': 276.8421,
        'label': 'Red Pattern position',
    })
    t.node('NodeFrame', 'Frame.002', props={
        'location': (23.052631, 288.5263),
        'width': 198.73685,
        'height': 280.0,
        'label': 'Green Pattern position',
    })
    t.node('NodeFrame', 'Frame.003', props={
        'location': (23.052631, -4.526306),
        'width': 198.73685,
        'height': 276.84207,
        'label': 'Blue Pattern position',
    })
    t.node('ShaderNodeUVMap', 'UV Map', props={
        'location': (-451.01825, 43.864838),
        'width': 150.0,
    })
    t.node('ShaderNodeGroup', 'Group.004', parent='Frame.001', inputs={'Scale X': 32.0, 'Scale Y': 32.0, 'Position X': 8.0, 'Position Y': 8.0}, props={
        'node_tree': lib.group('Scale Vector'),
        'location': (29.247665, -39.80211),
    })
    t.node('ShaderNodeGroup', 'Group.006', parent='Frame.003', inputs={'Scale X': 32.0, 'Scale Y': 32.0, 'Position X': 8.0, 'Position Y': 8.0}, props={
        'node_tree': lib.group('Scale Vector'),
        'location': (29.316986, -39.834564),
    })
    t.node('NodeGroupOutput', 'Group Output', props={
        'location': (270.3202, 66.71073),
        'width': 223.42773,
    })
    t.node('NodeReroute', 'Reroute', props={
        'location': (-212.81473, -59.36873),
        'socket_idname': 'NodeSocketVector',
    })
    t.node('NodeReroute', 'Reroute.001', props={
        'location': (241.01004, -72.5833),
        'socket_idname': 'NodeSocketVector',
    })
    t.node('ShaderNodeGroup', 'Group.005', parent='Frame.002', inputs={'Scale X': 32.0, 'Scale Y': 32.0, 'Position X': 8.0, 'Position Y': 8.0}, props={
        'node_tree': lib.group('Scale Vector'),
        'location': (29.316986, -39.372818),
    })
    t.node('ShaderNodeGroup', 'Group', parent='Frame', inputs={'Scale X': 32.0, 'Scale Y': 32.0, 'Position X': 8.0, 'Position Y': 8.0}, props={
        'node_tree': lib.group('Scale Vector'),
        'location': (29.213425, -39.454285),
    })

    t.link('Group', 'Coordinates', 'Group Output', 'Pattern position (base)')
    t.link('Reroute.001', 'Output', 'Group Output', 'Pattern position (red)')
    t.link('Group.005', 'Coordinates', 'Group Output', 'Pattern position (green)')
    t.link('Group.006', 'Coordinates', 'Group Output', 'Pattern position (blue)')
    t.link('UV Map', 'UV', 'Group', 'UV Map')
    t.link('UV Map', 'UV', 'Group.004', 'UV Map')
    t.link('UV Map', 'UV', 'Group.005', 'UV Map')
    t.link('Reroute', 'Output', 'Group.006', 'UV Map')
    t.link('UV Map', 'UV', 'Reroute', 'Input')
    t.link('Group.004', 'Coordinates', 'Reroute.001', 'Input')
    return t
